#include <bits/stdc++.h>
using namespace std;

int main() {
    ifstream fin("/workdir/data/parking.txt");
    ofstream fout("/workdir/answer.txt");

    int n, m;
    fin >> n >> m;

    vector<string> grid(n);
    for (int i = 0; i < n; i++) fin >> grid[i];

    // right[i][j] = number of consecutive empty cells to the right starting from (i,j)
