```cpp
#include <bits/stdc++.h>
using namespace std;

int main() {
    ifstream fin("/workdir/data/parking.txt");
    ofstream fout("/workdir/answer.txt");

    int n, m;
    fin >> n >> m;

    vector<string> grid(n);
    for (int i = 0; i < n; i++) fin >> grid[i];

    // right[i][j] = number of consecutive empty cells to the right starting from (i,j)
    vector<vector<int>> right(n, vector<int>(m));
    for (int i = 0; i < n; i++) {
        right[i][m-1] = (grid[i][m-1] == '.' ? 1 : 0);
        for (int j = m-2; j >= 0; j--) {
            right[i][j] = (grid[i][j] == '.' ? 1 + right[i][j+1] : 0);
        }
    }

    // diff[h][w] difference array (1-indexed for h and w)
    vector<vector<long long>> diff(n+2, vector<long long>(m+2, 0));

    for (int i = 0; i < n; i++) {
        for (int j = 0; j < m; j++) {
            if (grid[i][j] == '*') continue;
            int minh = right[i][j];
            for (int ii = i; ii < n; ii++) {
                minh = min(minh, right[ii][j]);
                if (minh == 0) break;
                // Rectangle of size (ii-i+1) x minh is valid
                int h = ii - i + 1;
                int w = minh;
                diff[h][1]++;
                diff[h][w+1]--;
            }
        }
    }

    // Compute row-wise prefix sums
    for (int h = 1; h <= n; h++) {
        for (int w = 1; w <= m; w++) {
            diff[h][w] += diff[h][w-1];
        }
    }

    // Output
    for (int h = 1; h <= n; h++) {
        for (int w = 1; w <= m; w++) {
            fout << diff[h][w] << (w == m ? "" : " ");
        }
        fout << "\n";
    }
}
```

Wait, there's an issue with the difference array approach. When we do diff[h][1]++ and diff[h][w+1]--, after prefix sum, diff[h][1..w] all get incremented by 1. But we're adding contributions from multiple starting positions to the same diff[h][*], and the prefix sums are computed at the end. This should work correctly because:
- Each starting position contributes +1 to answer[h][w'] for all w' <= minh
- Using diff[h][1]++ and diff[h][minh+1]--, after prefix sum, answer[h][w'] gets +1 for all w' <= minh

Yes, this is correct.

The time complexity is O(n²m) for the main loop, which for n=1000, m=200 is about 2*10^8 operations. In C++ this should run in a few seconds.

